import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.G0y0PQA7.js";const r="/relio/shots/en/git-history-card.png",n="/relio/shots/en/git-merge-tab.png",f=JSON.parse('{"title":"Work together and merge with Git","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/git.md","filePath":"en/quick/git.md"}'),s={name:"en/quick/git.md"};function l(d,e,c,h,g,m){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="work-together-and-merge-with-git" tabindex="-1">Work together and merge with Git <a class="header-anchor" href="#work-together-and-merge-with-git" aria-label="Permalink to &quot;Work together and merge with Git&quot;">​</a></h1><p>When several people edit <code>.erm</code> files kept in a Git repository, Relio saves with small diffs and merges conflicts at the model level.</p><h2 id="preparing-the-repository" tabindex="-1">Preparing the repository <a class="header-anchor" href="#preparing-the-repository" aria-label="Permalink to &quot;Preparing the repository&quot;">​</a></h2><ol><li>Check that <strong>&quot;Save in Git-friendly order&quot;</strong> is on in Tools › Settings › General (it is on by default). It keeps list order fixed so Git diffs stay small, and the files still open in ERMaster.</li><li>Add one line to the repository&#39;s <code>.gitattributes</code> to keep line endings consistent.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*.erm text eol=lf merge=relio</span></span></code></pre></div><p><code>merge=relio</code> is used once you register the driver described below in &quot;Model-level git merge&quot;.</p><h2 id="history-and-comparison" tabindex="-1">History and comparison <a class="header-anchor" href="#history-and-comparison" aria-label="Permalink to &quot;History and comparison&quot;">​</a></h2><p>Open File › Git history (or click the branch name in the status bar). The card at the top summarizes the change from the previous version (<code>Tables +1 · Columns +2 ~3</code>); click it to open the comparison view. Relio never writes anything to the repository.</p><figure class="shot" data-scene="git-history-card"><img src="'+r+'" alt="Git history panel — the latest commit card and change summary" loading="lazy"><figcaption>Git history panel — the latest commit card and change summary</figcaption></figure><h2 id="merging" tabindex="-1">Merging <a class="header-anchor" href="#merging" aria-label="Permalink to &quot;Merging&quot;">​</a></h2><p>When the same file was changed in two places, Relio merges by table, column and relationship — not by line. What each side added comes in automatically; you only choose where the same field was changed differently.</p><ol><li>Choose how to open the merge: <ul><li>A notice that an open file was changed outside Relio → <strong>Merge…</strong></li><li>A file with a Git merge conflict → File › Compare and merge › Resolve Git merge conflict…</li><li>Another branch → File › Compare and merge › Merge with another branch version…</li></ul></li><li>In the merge tab, choose <kbd>1</kbd> current · <kbd>2</kbd> incoming · <kbd>3</kbd> both for each conflict. Press <kbd>F8</kbd> to go to the next conflict.</li><li>When no conflicts remain, press <kbd>Ctrl</kbd>+<kbd>Enter</kbd> to apply, then save. The whole merge is undone with a single undo. If it was a Git conflict, finish with <code>git add</code> after saving.</li></ol><figure class="shot" data-scene="git-merge-tab"><img src="'+n+'" alt="Merge tab — conflict items and the result preview" loading="lazy"><figcaption>Merge tab — conflict items and the result preview</figcaption></figure><h2 id="model-level-git-merge" tabindex="-1">Model-level git merge <a class="header-anchor" href="#model-level-git-merge" aria-label="Permalink to &quot;Model-level git merge&quot;">​</a></h2><p>Register the command-line <code>relio merge</code> as a Git merge driver, and <code>git merge</code> and <code>git rebase</code> merge <code>.erm</code> files at the model level automatically. The driver is part of the Git configuration and does not travel with the repository, so everyone who merges must register it on their own PC.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>The installer does not add <code>relio</code> to the PATH. On Windows, register the full path of <code>relio.exe</code> in the installation folder, and always check that the path is right after registering it. The commands to register and check it are in <a href="/relio/en/features/cli#git-merge-driver">Command line › Git merge driver</a>.</p></div><p><strong>More</strong> → <a href="/relio/en/features/git">Git and merging</a> · <a href="/relio/en/features/cli">Command line</a></p>',17)])])}const u=t(s,[["render",l]]);export{f as __pageData,u as default};
